import React, { useState, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import './Scan.css';

const Scan = () => {
  const [selectedImage, setSelectedImage] = useState(null);
  const [analysisResult, setAnalysisResult] = useState(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const fileInputRef = useRef(null);
  const { currentUser } = useAuth();

  const handleImageUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target.result);
        setAnalysisResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const analyzeImage = () => {
    if (!selectedImage) return;

    setIsAnalyzing(true);

    // Simulate API call delay
    setTimeout(() => {
      const mockResults = [
        { 
          disease: 'Cassava Mosaic Virus', 
          confidence: 92, 
          treatment: 'Remove and destroy infected plants. Use certified virus-free planting materials.',
          prevention: 'Plant resistant varieties and control whitefly populations.'
        },
        { 
          disease: 'Maize Rust', 
          confidence: 87, 
          treatment: 'Apply fungicide containing chlorothalonil. Remove severely infected leaves.',
          prevention: 'Plant resistant varieties and ensure proper crop rotation.'
        },
        { 
          disease: 'Healthy', 
          confidence: 96, 
          treatment: 'No treatment needed - plant is healthy',
          prevention: 'Continue current maintenance practices.'
        },
        { 
          disease: 'Tomato Blight', 
          confidence: 78, 
          treatment: 'Apply copper-based fungicide. Remove and destroy infected plant parts.',
          prevention: 'Rotate crops and avoid overhead watering.'
        }
      ];

      const randomResult = mockResults[Math.floor(Math.random() * mockResults.length)];
      setAnalysisResult(randomResult);
      setIsAnalyzing(false);
    }, 3000);
  };

  const resetScan = () => {
    setSelectedImage(null);
    setAnalysisResult(null);
  };

  return (
    <div className="scan-page">
      <div className="scan-header">
        <h1>AI Crop Disease Scanner</h1>
        <p>Welcome back, {currentUser.name}! Upload a photo of your crop leaves for instant disease identification.</p>
      </div>

      <div className="scanner-container">
        <div className="upload-section">
          <div 
            className="upload-area"
            onClick={() => fileInputRef.current?.click()}
          >
            {selectedImage ? (
              <div className="image-preview">
                <img src={selectedImage} alt="Selected crop" />
                <button className="change-image-btn" onClick={(e) => {
                  e.stopPropagation();
                  resetScan();
                }}>
                  Change Image
                </button>
              </div>
            ) : (
              <div className="upload-placeholder">
                <div className="upload-icon">📷</div>
                <p>Click to upload an image of crop leaves</p>
                <small>Supported formats: JPG, PNG, WebP (Max 10MB)</small>
              </div>
            )}
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleImageUpload}
              accept="image/*"
              style={{ display: 'none' }}
            />
          </div>
        </div>

        {selectedImage && (
          <div className="analysis-section">
            <button 
              className="analyze-btn"
              onClick={analyzeImage}
              disabled={isAnalyzing}
            >
              {isAnalyzing ? (
                <>
                  <div className="spinner"></div>
                  Analyzing with AI...
                </>
              ) : (
                'Analyze with AI'
              )}
            </button>

            {analysisResult && (
              <div className="result-card">
                <h3>AI Analysis Complete</h3>
                <div className={`result-status ${analysisResult.disease === 'Healthy' ? 'healthy' : 'diseased'}`}>
                  {analysisResult.disease === 'Healthy' ? '✅ Healthy Plant' : `⚠️ ${analysisResult.disease}`}
                </div>
                <div className="confidence">
                  AI Confidence: <span>{analysisResult.confidence}%</span>
                </div>

                <div className="treatment-info">
                  <h4>Recommended Treatment:</h4>
                  <p>{analysisResult.treatment}</p>
                </div>

                {analysisResult.disease !== 'Healthy' && (
                  <div className="prevention-info">
                    <h4>Prevention Tips:</h4>
                    <p>{analysisResult.prevention}</p>
                  </div>
                )}

                <button className="new-scan-btn" onClick={resetScan}>
                  Scan Another Image
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="scan-tips">
        <h3>Tips for Best AI Results:</h3>
        <div className="tips-grid">
          <div className="tip-card">
            <div className="tip-icon">☀️</div>
            <p>Take photos in good natural lighting</p>
          </div>
          <div className="tip-card">
            <div className="tip-icon">🎯</div>
            <p>Focus clearly on the affected leaves</p>
          </div>
          <div className="tip-card">
            <div className="tip-icon">📐</div>
            <p>Include multiple angles if possible</p>
          </div>
          <div className="tip-card">
            <div className="tip-icon">🌿</div>
            <p>Capture both healthy and affected areas</p>
          </div>
        </div>
      </div>

      <div className="scan-history">
        <h3>Recent Scans</h3>
        <div className="history-placeholder">
          <p>Your scan history will appear here</p>
          <small>Start scanning to build your disease detection history</small>
        </div>
      </div>
    </div>
  );
};

export default Scan;
